var canReach = function(s, minJump, maxJump) {
    if (s[s.length - 1] !== '0') return false;

    const n = s.length;
    const arr = Array(n + 1).fill(0);
    arr[0] = 1;
    arr[1] = -1;
    let total = 0;

    for (let i = 0; i < n; i++) {
        total += arr[i];

        if (s[i] === '0' && total > 0 && i + minJump < n) {
            arr[i + minJump]++;
            arr[Math.min(i + maxJump + 1, n)]--;
        }
    }

    return total > 0;
};
